"""Seven branching, texture-free miniature Blender trees; paired web/compact meshes, one material.
Run with Blender --background --python 树木模型/build_trees.py.
"""
import bpy, math, random, json, struct, hashlib, shutil
from pathlib import Path
from mathutils import Vector
ROOT=Path(__file__).resolve().parent; OUT=ROOT/'web'; OUT.mkdir(exist_ok=True)
bpy.ops.object.select_all(action='SELECT');bpy.ops.object.delete(use_global=False)
mat=bpy.data.materials.new('Foliage and bark · vertex colour');mat.use_nodes=True
nodes=mat.node_tree.nodes; nodes.clear(); bsdf=nodes.new('ShaderNodeBsdfPrincipled'); output=nodes.new('ShaderNodeOutputMaterial'); mat.node_tree.links.new(bsdf.outputs['BSDF'],output.inputs['Surface']); bsdf.inputs['Roughness'].default_value=.96
color=nodes.new('ShaderNodeVertexColor');color.layer_name='Color';mat.node_tree.links.new(color.outputs['Color'],bsdf.inputs['Base Color'])
import sys
sys.path.insert(0,str(ROOT))
from tree_shapes import PALETTE,make_tree
objects=[]
for species in PALETTE:
 for compact in [False,True]:objects.append(make_tree(species,compact,mat))
bpy.ops.wm.save_as_mainfile(filepath=str(OUT/'树木_网页版.blend'))
file=OUT/'trees.glb';bpy.ops.export_scene.gltf(filepath=str(file),export_format='GLB',export_yup=True,export_normals=True,export_texcoords=False,export_materials='EXPORT',export_vertex_color='ACTIVE',export_all_vertex_colors=False,export_cameras=False,export_lights=False)
b=file.read_bytes();doc=json.loads(b[20:20+struct.unpack_from('<I',b,12)[0]])
meshes={m['name']:sum(doc['accessors'][p.get('indices',p['attributes']['POSITION'])]['count']//3 for p in m['primitives']) for m in doc['meshes']}
assert max(meshes.values())<=400,meshes
stats={'file':'trees.glb','glb_bytes':len(b),'sha256':hashlib.sha256(b).hexdigest(),'version':'miniature-trees-v2-'+hashlib.sha256(b).hexdigest()[:8],'triangles':meshes,'total_library_triangles':sum(meshes.values()),'materials':len(doc['materials']),'textures':len(doc.get('images',[])),'coordinate_convention':'glTF Y-up, trunk foot origin; one mesh per species and detail level','source_blend':'../../../树木模型/树木_分组可编辑.blend','web_blend':'../../../树木模型/web/树木_网页版.blend','generator':'../../../树木模型/build_trees.py','max_triangles_per_tree':400,'vertex_colors':True,'custom_canopy_normals':True,'geometry_source':'../../../树木模型/tree_shapes.py'}
(ROOT.parent/'sandbox-app/src/tree-asset.js').write_text("// Generated by 树木模型/build_trees.py; cache key follows exported bytes.\nimport {assetUrl} from './asset-url.js';\nexport const TREE_ASSET=assetUrl('models/trees.glb?v="+stats['version']+"');\n")
(OUT/'stats.json').write_text(json.dumps(stats,ensure_ascii=False,indent=2));shutil.copy2(file,ROOT.parent/'sandbox-app/public/models/trees.glb')
manifest_path=ROOT.parent/'sandbox-app/public/models/manifest.json';manifest=json.loads(manifest_path.read_text());manifest['vegetation']=stats;manifest_path.write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
# An editable, labelled lineup, separate from the origin-aligned runtime asset.
for i,obj in enumerate(objects):obj.location=((i//2)*4.4,4 if i%2 else 0,0)
bpy.ops.wm.save_as_mainfile(filepath=str(ROOT/'树木_分组可编辑.blend'))
# Render the actual exported geometry's full-detail shapes, not a concept image.
for o in objects:o.hide_render=o.name.endswith('_compact')
bpy.ops.mesh.primitive_plane_add(size=200,location=(12,0,-.02));floor=bpy.context.object
m=bpy.data.materials.new('Warm paper');m.diffuse_color=(.78,.79,.75,1);floor.data.materials.append(m)
bpy.ops.object.camera_add(location=(21,-33,15));cam=bpy.context.object;cam.rotation_euler=(Vector((13.2,0,1.8))-cam.location).to_track_quat('-Z','Y').to_euler();cam.data.type='ORTHO';cam.data.ortho_scale=31;bpy.context.scene.camera=cam
bpy.ops.object.light_add(type='AREA',location=(8,-10,18));bpy.context.object.data.energy=2300;bpy.context.object.data.shape='DISK';bpy.context.object.data.size=12
sc=bpy.context.scene;sc.render.engine='CYCLES';sc.cycles.samples=48;sc.world.use_nodes=True;sc.world.node_tree.nodes['Background'].inputs['Color'].default_value=(.72,.78,.85,1);sc.world.node_tree.nodes['Background'].inputs['Strength'].default_value=.55;sc.view_settings.view_transform='AgX';sc.render.resolution_x=1800;sc.render.resolution_y=620;sc.render.resolution_percentage=100;sc.render.image_settings.file_format='PNG';sc.render.filepath=str(OUT/'树木实模预览.png');bpy.ops.render.render(write_still=True)
print(json.dumps(stats,ensure_ascii=False,indent=2))
